#include <bits/stdc++.h>
using namespace std;

int main() {
    int n; long long target;
    if (scanf("%d %lld", &n, &target) != 2) return 0;
    unordered_set<long long> s;
    s.reserve(2 * n);
    for (int i = 0; i < n; i++) { long long x; scanf("%lld", &x); s.insert(x); }
    // target > 0, so each pair is counted once from its smaller value.
    long long count = 0;
    for (long long x : s) count += s.count(x + target);
    printf("%lld\n", count);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken(); int n = (int) st.nval;
        st.nextToken(); long target = (long) st.nval;
        HashSet<Long> s = new HashSet<>(2 * n);
        for (int i = 0; i < n; i++) { st.nextToken(); s.add((long) st.nval); }
        // target > 0, so each pair is counted once from its smaller value.
        long count = 0;
        for (long x : s) if (s.contains(x + target)) count++;
        System.out.println(count);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReaderSize(os.Stdin, 1<<16)
	var n int
	var target int64
	fmt.Fscan(in, &n, &target)
	s := make(map[int64]struct{}, n)
	for i := 0; i < n; i++ {
		var x int64
		fmt.Fscan(in, &x)
		s[x] = struct{}{}
	}
	// target > 0, so each pair is counted once from its smaller value.
	count := 0
	for x := range s {
		if _, ok := s[x+target]; ok {
			count++
		}
	}
	fmt.Println(count)
}
